window.AUTH=window.AUTH||{};window.AUTH["25-332"]={"d":"25-332","id":"2025/25-332","n":"Trump v. Slaughter","briefs":[{"k":"petitioner","label":"Brief of petitioners Donald J. Trump, et al.","date":"2025-10-10","url":"https://www.supremecourt.gov/DocketPDF/25/25-332/379414/20251010163717598_25-332PetrBr.pdf","side":"pet","n":127},{"k":"respondent","label":"Brief of respondent Rebecca Kelly Slaughter","date":"2025-11-07","url":"https://www.supremecourt.gov/DocketPDF/25/25-332/383932/20251107161927499_Slaughter%20respondent%20brief%20final.pdf","side":"res","n":70},{"k":"reply","label":"Reply of petitioners Donald J. Trump, President of the United States, et al.","date":"2025-11-24","url":"https://www.supremecourt.gov/DocketPDF/25/25-332/385592/20251124134517963_25-332reply.pdf","side":"pet","n":44}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/609us2r62_g314.pdf","tr":true,"items":[{"t":"case","label":"Abramowitz v. Lake","cite":"2025 WL 2480354","y":2025,"court":"D.D.C. Aug. 28","by":{"0":"38"}},{"t":"case","label":"Aviel v. Gor","cite":"780 F. Supp. 3d 1","y":2025,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/780/1/","by":{"0":"38"}},{"t":"case","label":"Ashcroft v. al-Kidd","cite":"563 U.S. 731","y":2011,"id":"2010/10-98","sc":1,"sum":"The Court held that former Attorney General John Ashcroft was entitled to qualified immunity.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Axon Enterprise, Inc. v. FTC","cite":"598 U.S. 175","y":2023,"id":"2022/21-86","sc":1,"ar":1,"sum":"The statutory review schemes set out in the Securities Exchange Act and Federal Trade Commission Act do not displace a district court’s federal-question jurisdiction over claims challenging as unconstitutional the structure or existence of the SEC or FTC.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"46"}},{"t":"case","label":"Baker v. Carr","cite":"369 U.S. 186","y":1962,"id":"1960/6","sc":1,"sum":"The Court found that redistricting issues present justiciable questions, and in which the Court reframed its political question doctrine.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Berry v. Reagan","cite":"1983 WL 538","y":1983,"court":"D.D.C. Nov. 14","by":{"0":"40"}},{"t":"case","label":"Bessent v. Dellinger","cite":"145 S. Ct. 515","y":2025,"url":"https://www.courtlistener.com/c/S.%20Ct./145/515/","sc":1,"by":{"0":"39, 40"}},{"t":"case","label":"Bloch v. Executive Office of the President","cite":"164 F. Supp. 3d 841","y":2016,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/164/841/","by":{"0":"47","1":"52, 53"}},{"t":"case","label":"Bowsher v. Synar","cite":"478 U.S. 714","y":1986,"id":"1985/85-1377","sc":1,"op":6,"sum":"The Court found that the duties which the Congress delegated to the Comptroller General did violate the doctrine of separation of powers and were unconstitutional. A two step process led Chief Justice Burger to arrive at this conclusion.","sumSrc":"Oyez","by":{"0":"16, 24","1":"20","2":"13"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"op":4,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"0":"19, 26"}},{"t":"case","label":"Cheney v. U.S. District Court","cite":"542 U.S. 367","y":2004,"id":"2003/03-475","sc":1,"ar":1,"sum":"The Court sent the case back to the D.C. Court of Appeals, arguing that the appellate court should have considered separation-of-powers claims and was wrong to conclude it lacked authority to order District Court discovery to stop.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"City of Arlington v. FCC","cite":"569 U.S. 290","y":2013,"id":"2012/11-1545","sc":1,"op":1,"ar":3,"sum":"The Court found that the courts must apply the Chevron doctrine and defer to an agency's interpretation of its jurisdiction when that jurisdiction is called into question.","sumSrc":"Oyez","by":{"0":"24, 34","1":"33"}},{"t":"case","label":"Citizens United v. FEC","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"sum":"The Court held that corporate funding of independent political broadcasts in elections cannot be limited under the First Amendment.","sumSrc":"Oyez","by":{"0":"32","2":"17"}},{"t":"case","label":"Collins v. Yellen","cite":"594 U.S. 220","y":2021,"id":"2020/19-422","sc":1,"op":1,"sum":"Explaining that the Appointments Clause “guarantees accountability” for poorly performing offcers.","sumSrc":"opinion","by":{"0":"4, 16, 33, 36, 44","1":"14, 34","2":"3, 8"}},{"t":"case","label":"Consumers’ Research v. CPSC","cite":"91 F.4th 342","y":2024,"url":"https://www.courtlistener.com/c/F.4th/91/342/","by":{"0":"35"}},{"t":"case","label":"Dobbs v. Jackson Women’s Health Organization","cite":"597 U.S. 215","y":2022,"id":"2021/19-1392","sc":1,"op":4,"sum":"The Constitution does not confer a right to abortion; Roe v. Wade, 410 U. S. 113, and Planned Parenthood of Southeastern Pa. v. Casey, 505 U. S. 833, are overruled; the authority to regulate abortion is returned to the people and their elected representatives.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"11, 30, 33, 34"}},{"t":"case","label":"Elgin v. Department of Treasury","cite":"567 U.S. 1","y":2012,"id":"2011/11-45","sc":1,"sum":"The Court held that the Civil Service Reform Act precludes federal courts' jurisdiction in cases where federal employees seek equitable relief.","sumSrc":"Oyez","by":{"0":"45, 46"}},{"t":"case","label":"Edwards v. Vannoy","cite":"593 U.S. 255","y":2021,"id":"2020/19-5807","sc":1,"sum":"The jury-unanimity rule announced in Ramos v. Louisiana, 590 U. S. ___, does not apply retroactively on federal collateral review.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"35"}},{"t":"case","label":"FCC v. Consumers’ Research","cite":"145 S. Ct. 2482","y":2025,"id":"2024/24-354","sc":1,"sum":"The universal-service contribution scheme does not violate the Constitution’s nondelegation doctrine; Congress sufficiently guided and constrained the discretion that it lodged with the Federal Communications Commission to implement that scheme, and the FCC has retained all decision-making authority within that sphere, relying on the Universal Service Administrative Company only for non-binding advice.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"4, 20, 33"}},{"t":"case","label":"FTC v. Ruberoid Co.","cite":"343 U.S. 470","y":1952,"id":"scdb/1951-083","sc":1,"op":2,"sum":"A company which was engaged in the manufacture of roofing materials was found by the Federal Trade Commission to have discriminated among customers in the prices charged for its products. The Commission held that the discriminations violated 6 2 (a) of the Clayton Act, as amended, and ordered the company to cease and desist from selling \"products of like grade and quality to any purchaser at prices lower than those …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"Fornaro v. James","cite":"416 F.3d 63","y":2005,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/416/63/","by":{"0":"45, 46"}},{"t":"case","label":"Franchise Tax Board v. Hyatt","cite":"587 U.S. 230","y":2019,"id":"2018/17-1299","sc":1,"sum":"Nevada v. Hall, 440 U. S. 410, is overruled; States retain their sovereign immunity from private suits brought in courts of other States.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"31"}},{"t":"case","label":"Franklin v. Massachusetts","cite":"505 U.S. 788","y":1992,"id":"1991/91-1502","sc":1,"op":2,"sum":"Evaluating the Secretary's chosen procedure under Article I Section 2 of the Constitution, however, Justice O'Connor ruled that the decision to include overseas personnel of the Department of Defense was a reasonable interpretation of the Constitution's intent. \"The Secretary's judgment does not hamper the underlying constitutional goal of equal representation, but, assuming that employees temporarily stationed abroad have indeed retained their ties to their home states, actually promotes equality,\" wrote Justice O'Connor.","sumSrc":"Oyez","by":{"0":"44","1":"49, 50"}},{"t":"case","label":"Free Enterprise Fund v. PCAOB","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"op":13,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"5, 13-20, 22, 23, 26","1":"18-20, 25","2":"1, 3, 6, 7, 10-13, 16, 22"}},{"t":"case","label":"Great Lakes Dredge & Dock Co. v. Huffman","cite":"319 U.S. 293","y":1943,"id":"scdb/1942-144","sc":1,"by":{"0":"42, 43","1":"44"}},{"t":"case","label":"Grupo Mexicano de Desarrollo S.A. v. Alliance Bond Fund, Inc.","cite":"527 U.S. 308","y":1999,"id":"1998/98-231","sc":1,"sum":"The Court held that the District Court lacked the authority to issue a preliminary injunction preventing defendants being sued by creditors from disposing of their assets pending adjudication of the creditor's contract claim for monetary damages because such a remedy was historically unavailable from a court of equity.","sumSrc":"Oyez","by":{"0":"41","1":"45"}},{"t":"case","label":"Harkrader v. Wadley","cite":"172 U.S. 148","y":1898,"id":"scdb/1898-024","sc":1,"sum":"The facts in the record show that there is no merit in the several objections to the jurisdiction of this court taken by the appellee in this case.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Harper v. Bessent","cite":"2025 WL 2049207","y":2025,"court":"D.D.C. July 22","op":1,"by":{"0":"38"}},{"t":"case","label":"Hecht Co. v. Bowles","cite":"321 U.S. 321","y":1944,"id":"scdb/1943-092","sc":1,"sum":"1. Under § 205 (a) of the Emergency Price Control Act of 1942, the grant of an injunction, upon application of the Administrator and a showing that the defendant has engaged in acts or practices violative of § 4 of the Act, is not mandatory but is in the discretion of the court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Howes v. Fields","cite":"565 U.S. 499","y":2012,"id":"2011/10-680","sc":1,"sum":"The Court held that a prisoner, currently held in jail, did not have his Miranda rights violated when he was questioned inside the jail for a different crime.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Humphrey’s Executor v. United States","cite":"295 U.S. 602","y":1935,"id":"1900-1940/295us602","sc":1,"op":29,"sum":"The unanimous Court found that the FTC Act was constitutional and that Humphrey's dismissal on policy grounds was unjustified. The Court reasoned that the Constitution had never given \"illimitable power of removal\" to the president. Justice Sutherland dismissed the government's main line of defense in this case which relied heavily on the Court's decision in Myers v. United States (1926).","sumSrc":"Oyez","by":{"0":"3, 8, 10, 11, 13, 21-25, 27, 28, 30, 31, 34, 36, 40","1":"2, 6, 7, 10-12, 18, 19, 22, 23, 26-28, 30-36, 38, 39","2":"2, 3, 5, 11-15, 17, 18"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"op":9,"ar":6,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"0":"29, 37","2":"11, 18"}},{"t":"case","label":"Kennedy v. Braidwood Management, Inc.","cite":"145 S. Ct. 2427","y":2025,"id":"2024/24-316","sc":1,"ar":2,"sum":"Members of the U. S. Preventive Services Task Force are inferior officers whose appointment by the Secretary of the Department of Health and Human Services is consistent with the Appointments Clause. Art. II, §2, cl. 2.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"14, 31, 44","2":"9, 12, 16"}},{"t":"case","label":"Kennedy v. Bremerton School District","cite":"597 U.S. 507","y":2022,"id":"2021/21-418","sc":1,"op":3,"sum":"The Free Exercise and Free Speech Clauses of the First Amendment protect an individual engaging in a personal religious observance from government reprisal; the Constitution neither mandates nor permits the government to suppress such religious expression.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"30"}},{"t":"case","label":"Kimble v. Marvel Entertainment, LLC","cite":"576 U.S. 446","y":2015,"id":"2014/13-720","sc":1,"op":1,"sum":"The Court determined that its earlier decision in Brulotte v. Thys Co. , which held that a patentee cannot continue to receive royalties after the expiration of the patent, should be upheld.","sumSrc":"Oyez","by":{"0":"31","1":"31"}},{"t":"case","label":"Lemon v. Kurtzman","cite":"403 U.S. 602","y":1971,"id":"1970/89","sc":1,"sum":"The Court found that Pennsylvania and Rhode Island statutes granting salary supplements to teachers at \"church-related educational institutions\" was unconstitutional for violating the Establishment Clause of the First Amendment. The case established the Lemon Test for determining if the government is becoming too involved in religious activities.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Loper Bright Enterprises v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"op":4,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"36","1":"39"}},{"t":"case","label":"Macauley v. Waterman S.S. Corp.","cite":"327 U.S. 540","y":1946,"id":"scdb/1945-065","sc":1,"sum":"The Maritime Commission Price Adjustment Board notified respondent that it had been assigned to renegotiate respondent's war contracts with the Commission pursuant to the Renegotiation Act and requested respondent to attend an initial conference and to supply information. Respondent denied the Board's authority on the ground that its contracts were with a British ministry and not with the Maritime Commission. The …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Marbury v. Madison","cite":"1 Cranch 137","y":1803,"url":"https://www.courtlistener.com/c/Cranch/1/137/","op":3,"by":{"0":"43","2":"21"}},{"t":"case","label":"Mississippi v. Johnson","cite":"4 Wall. 475","y":1867,"url":"https://www.courtlistener.com/c/Wall./4/475/","by":{"0":"43"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"op":3,"ar":1,"sum":"Explaining that Humphrey's stands only for the proposition that there would be “no strict constitutional impediment to a `branchless' agency” that exercises “no governmental power”.","sumSrc":"opinion","by":{"0":"33","2":"9, 13"}},{"t":"case","label":"Montejo v. Louisiana","cite":"556 U.S. 778","y":2009,"id":"2008/07-1529","sc":1,"op":1,"sum":"The Court held that after the appointment of an attorney, a defendant does not necessarily need to take additional steps to accept the appointment in order to secure the protections of the Sixth Amendment.","sumSrc":"Oyez","by":{"0":"32","1":"39"}},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S. 654","y":1988,"id":"1987/87-1279","sc":1,"op":17,"ar":7,"sum":"Rejecting “the implication Sotomayor, J., dissenting of some dicta in Myers” that “the President's power to remove . . . was . . . `all-inclusive' ”.","sumSrc":"opinion","by":{"0":"5, 24, 31, 32, 34, 37","1":"24, 34","2":"15, 17, 18"}},{"t":"case","label":"Munaf v. Geren","cite":"553 U.S. 674","y":2008,"id":"2007/06-1666","sc":1,"sum":"Held that the habeas corpus statute extends to American citizens held overseas by American forces operating subject to an American chain of command even if part of a larger multinational force.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Myers v. United States","cite":"272 U.S. 52","y":1926,"id":"1900-1940/272us52","sc":1,"op":13,"sum":"After tracing legislative debate of the First Congress in 1789 which dealt with the interpretation of the President's appointment power, Chief Justice Taft concluded that the power to remove appointed officers is vested in the President alone. According to Taft, to deny the President that power would not allow him to \"discharge his own constitutional duty of seeing that the laws be faithfully executed.\".","sumSrc":"Oyez","by":{"0":"4, 9, 10, 16-19, 29, 37, 40","1":"18, 27, 29, 30, 37","2":"4, 5, 7, 10, 11"}},{"t":"case","label":"Nixon v. Fitzgerald","cite":"457 U.S. 731","y":1982,"id":"1981/79-1738","sc":1,"op":1,"sum":"The Court held that the President \"is entitled to absolute immunity from damages liability predicated on his official acts.\" This sweeping immunity, argued Justice Powell, was a function of the \"President's unique office, rooted in the constitutional tradition of separation of powers and supported by our history.\".","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Palmore v. United States","cite":"411 U.S. 389","y":1973,"id":"1972/72-11","sc":1,"sum":"1 1. The District of Columbia Code is not a state statute for purposes of § 1257 (2), and the lower court's upholding of the federal statute is therefore not reviewable by appeal but by certiorari.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Parsons v. United States","cite":"167 U.S. 324","y":1897,"id":"scdb/1896-203","sc":1,"op":3,"ar":3,"sum":"The President has power to remove a district attorney of the United States, when such removal occurs within four years from the date of the attorney’s appointment, and, with the advice and consent of the Senate, to appoint a successor to him.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"16, 18, 40","2":"9"}},{"t":"case","label":"Perlmutter v. Blanche","cite":"2025 WL 2627965","y":2025,"court":"D.C. Cir. Sept. 10","ar":3,"by":{"0":"38"}},{"t":"case","label":"PHH Corp. v. CFPB","cite":"881 F.3d 75","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/881/75/","op":2,"by":{"0":"26, 29, 30, 33","1":"2, 16, 17, 20, 21, 36"}},{"t":"case","label":"Powell v. McCormack","cite":"395 U.S. 486","y":1969,"id":"1968/138","sc":1,"ar":1,"sum":"After analyzing the Framers' debates on this issue, Chief Justice Warren concluded that since Powell had been lawfully elected by his constituents and since he met the constitutional requirements for membership in the House, that the chamber was powerless to exclude him.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Raines v. Byrd","cite":"521 U.S. 811","y":1997,"id":"1996/96-1671","sc":1,"sum":"In a 7-to-2 decision, which avoided the question of the Act's constitutionality, the Court held that the individual congressmen lacked proper Article III standing to maintain their suit. The Court explained that the congressmen failed to show how the allegedly unconstitutional Act resulted in their personal injury, since it applied to the entire institution of Congress.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Ramos v. Louisiana","cite":"590 U.S. 83","y":2020,"id":"2019/18-5924","sc":1,"op":1,"ar":1,"sum":"The Court held that the Fourteenth Amendment fully incorporates the Sixth Amendment’s guarantee of a unanimous verdict against the states.","sumSrc":"Oyez","by":{"0":"30","2":"18"}},{"t":"case","label":"Ryan, LLC v. FTC","cite":"746 F. Supp. 3d 369","y":2024,"court":"N.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/746/369/","op":1,"by":{"0":"27"}},{"t":"case","label":"Samuels v. Mackell","cite":"401 U.S. 66","y":1971,"id":"1970/7","sc":1,"sum":"The Supreme Court held that the defendants would not suffer irreparable damages if the state trial continued. The Court also held that the district court should not have evaluated the case on the merits because of the pending statute court proceedings. Justice William O. Douglas concurred, writing that the New York laws were not obviously unconstitutional, so it was up to the state court to evaluate the matter.","sumSrc":"Oyez","by":{"0":"12, 42, 43"}},{"t":"case","label":"Seila Law LLC v. CFPB","cite":"591 U.S. 197","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/197/","sc":1,"op":36,"ar":31,"by":{"0":"2-4, 9, 10, 14-20, 22-27, 29, 32-34, 36","1":"1, 17, 19-24, 31-32, 34, 38","2":"1-8, 10, 13-17, 19"}},{"t":"case","label":"Shurtleff v. United States","cite":"189 U.S. 311","y":1903,"id":"scdb/1902-126","sc":1,"ar":3,"sum":"Where Congress creates an office and provides for the removal of the incumbent at any time for inefficiency, neglect of duty, or malfeasance in office, if the removal of the officer is sought to be made for any of those causes he is entitled to notice and a hearing; but if the President removes him without giving him notice and an opportunity to defend himself, it must be presumed that the removal was not made for …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"40, 44","2":"10"}},{"t":"case","label":"Space Exploration Technologies Corp. v. NLRB","cite":"2025 WL 2396748","y":2025,"court":"5th Cir. Aug. 19","op":2,"by":{"0":"35"}},{"t":"case","label":"Synar v. United States","cite":"626 F. Supp. 1374","y":1986,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./626/1374/","by":{"0":"26"}},{"t":"case","label":"Taylor v. Beckham (No. 1)","cite":"178 U.S. 548","y":1900,"id":"scdb/1899-087","sc":1,"sum":"By the constitution and laws of Kentucky, the determination of contests of the election of Governor and Lieutenant Governor is, and for a hundred years has been, committed to the General Assembly of that Commonwealth.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Trump v. Boyle","cite":"145 S. Ct. 2653","y":2025,"url":"https://www.courtlistener.com/c/S.%20Ct./145/2653/","sc":1,"by":{"0":"38"}},{"t":"case","label":"Trump v. CASA, Inc.","cite":"606 U.S. 831","y":2025,"id":"2024/24a884","sc":1,"sum":"Because universal injunctions likely exceed the equitable authority that Congress has granted to federal courts, the Court grants the Government’s applications for a partial stay of the injunctions entered below regarding the implementation and enforcement of President Trump’s Executive Order No. 14160, but only to the extent that the injunctions are broader than necessary to provide complete relief to each plaintiff with standing to sue.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"41","1":"40, 48, 50"}},{"t":"case","label":"Trump v. United States","cite":"603 U.S. 593","y":2024,"id":"2023/23-939","sc":1,"op":2,"sum":"The nature of Presidential power entitles a former President to absolute immunity from criminal prosecution for actions within his conclusive and preclusive constitutional authority; he is also entitled to at least presumptive immunity from prosecution for all his official acts; there is no immunity for unofficial acts.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"2, 4, 9, 16, 18, 25, 27, 31","1":"25-28","2":"1, 4"}},{"t":"case","label":"Trump v. Wilcox","cite":"145 S. Ct. 1415","y":2025,"url":"https://www.courtlistener.com/c/S.%20Ct./145/1415/","sc":1,"by":{"0":"3, 8, 29, 35, 42"}},{"t":"case","label":"United States v. Arthrex, Inc.","cite":"594 U.S. 1","y":2021,"id":"2020/19-1434","sc":1,"op":2,"sum":"Explaining that the Appointments Clause “guarantees accountability” for poorly performing offcers.","sumSrc":"opinion","by":{"0":"14, 18, 24"}},{"t":"case","label":"United States v. Duell","cite":"172 U.S. 576","y":1899,"id":"scdb/1898-058","sc":1,"sum":"An appeal to the Court of Appeals of the District of Columbia from the decision of the Commissioner of Patents in an interference controversy presents all the features of a civil case, a plaintiff, a defendant and a judge, and deals with a question judicial in its nature, in respect of which the judgment of the court is final, so far as the particular action of the Patent Office is concerned; and such judgment is …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"sum":"The CSRA, which affords to nonpreference eligibles in the excepted service no administrative or judicial review of adverse personnel action of the type involved here, precludes judicial review for those employees under the Tucker Act based on the Back Pay Act. The CSRA was designed to replace the haphazard arrangements that had built up over almost a century with one integrated system for administrative and judicial …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45-47","1":"52","2":"23"}},{"t":"case","label":"United States v. Perkins","cite":"116 U.S. 483","y":1866,"id":"scdb/1885-120","sc":1,"op":3,"ar":1,"sum":"Holding, in 1886, that inferior offcers appointed by a department head could be protected against at-will removal.","sumSrc":"opinion","by":{"0":"40"}},{"t":"case","label":"United States Institute of Peace v. Jackson","cite":"783 F. Supp. 3d 316","y":2025,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/783/316/","op":4,"by":{"0":"38"}},{"t":"case","label":"Walton v. House of Representatives","cite":"265 U.S. 487","y":1924,"id":"scdb/1923-182","sc":1,"sum":"A court of the United States, sitting as a court of equity, is wfthout jurisdiction of a suit to enjoin the prosecution of a proceeding to remove a state official from office. P. 490. Affirmed. APPeAL from a decree of the District. Court dismissing the billin a suit by the Governor of Oklahoma to enjoin the prosecution of impeachment proceedings in the state legislature as based on improper motives and as infringing …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"White v. Berry","cite":"171 U.S. 366","y":1898,"id":"scdb/1897-181","sc":1,"sum":"A court of equity has no jurisdiction over the appointment and removal of public officers, whether the power of removal is vested, as well as that of appointment, in executive or administrative boards or officers, or is entrusted to a judicial tribunal.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"12, 41-43","1":"45, 47, 48","2":"20, 21"}},{"t":"case","label":"Wiener v. United States","cite":"357 U.S. 349","y":1958,"id":"1957/52","sc":1,"op":6,"ar":12,"sum":"The Court held that the President did not have the authority to remove individuals from the War Claims Commission at will.","sumSrc":"Oyez","by":{"0":"30, 40","1":"18, 19, 50","2":"15"}},{"t":"case","label":"Wilcox v. Trump","cite":"775 F. Supp. 3d 215","y":2025,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/775/215/","op":1,"by":{"0":"35"}},{"t":"case","label":"Youngstown Sheet & Tube Co. v. Sawyer","cite":"343 U.S. 579","y":1952,"id":"1940-1955/343us579","sc":1,"op":3,"sum":"The Court held that the President did not have the right to seize control of most of the country's steel mills to negate the effects of a suspected strike during the Korean War.","sumSrc":"Oyez","by":{"0":"16","1":"2, 11, 25, 27, 28, 50"}},{"t":"const","label":"Article II","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"],["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"],["take-care","Take Care Clause"],["impeachment","Impeachment"]],"by":{"0":"5, 10-12, 16, 18, 24, 28, 29, 38","1":"9, 12, 22, 24, 26, 48, 49","2":"1, 2, 7, 8, 11, 16, 17, 19, 20"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"0":"24","1":"45"}},{"t":"usc","label":"5 U.S.C. § 5596","url":"https://www.law.cornell.edu/uscode/text/5/5596","by":{"0":"45"}},{"t":"usc","label":"15 U.S.C. § 6502","url":"https://www.law.cornell.edu/uscode/text/15/6502","subs":["(b)(1)"],"by":{"0":"26"}},{"t":"usc","label":"5 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/5/1101","by":{"0":"12, 45"}},{"t":"usc","label":"5 U.S.C. § 7511","url":"https://www.law.cornell.edu/uscode/text/5/7511","subs":["(b)(1)","(b)(2)","(b)(3)","(a)(1)(C)"],"stext":{"head":"§7511. Definitions; application","paras":[[0,"(a) For the purpose of this subchapter—"],[1,"(1) \"employee\" means—"],[2,"(A) an individual in the competitive service—"],[3,"(i) who is not serving a probationary or trial period under an initial appointment; or"],[3,"(ii) who has completed 1 year of current continuous service under other than a temporary appointment limited to 1 year or less;"],[2,"(B) a preference eligible in the excepted service who has completed 1 year of current continuous service in the same or similar positions—"],[3,"(i) in an Executive agency; or"],[3,"(ii) in the United States Postal Service or Postal Regulatory Commission; and"],[2,"(C) an individual in the excepted service (other than a preference eligible)—"],[3,"(i) who is not serving a probationary or trial period under an initial appointment pending conversion to the competitive service; or"],[3,"(ii) who has completed 2 years of current continuous service in the same or similar positions in an Executive agency under other than a temporary appointment limited to 2 years or less;"],[1,"(2) \"suspension\" has the same meaning as set forth in section 7501(2) of this title;"],[1,"(3) \"grade\" means a level of classification under a position classification system;"],[1,"(4) \"pay\" means the rate of basic pay fixed by law or administrative action for the position held by an employee; and"],[1,"(5) \"furlough\" means the placing of an employee in a temporary status without duties and pay because of lack of work or funds or other nondisciplinary reasons."],[0,"(b) This subchapter does not apply to an employee—"],[1,"(1) whose appointment is made by and with the advice and consent of the Senate;"],[1,"(2) whose position has been determined to be of a confidential, policy-determining, policy-making or policy-advocating character by—"],[2,"(A) the President for a position that the President has excepted from the competitive service;"],[2,"(B) the Office of Personnel Management for a position that the Office has excepted from the competitive service; or"],[2,"(C) the President or the head of an agency for a position excepted from the competitive service by statute;"],[1,"(3) whose appointment is made by the President;"],[1,"(4) who is receiving an annuity from the Civil Service Retirement and Disability Fund, or the Foreign Service Retirement and Disability Fund, based on the service of such employee;"],[1,"[(5) Repealed. Pub. L. 114–328, div. A, title V, §512(c), Dec. 23, 2016, 130 Stat. 2112.]"],[1,"(6) who is a member of the Foreign Service, as described in section 103 of the Foreign Service Act of 1980;"],[1,"(7) whose position is within the Central Intelligence Agency or the Government Accountability Office;"],[1,"(8) whose position is within the United States Postal Service, the Postal Regulatory Commission, the Panama Canal Commission, the Tennessee Valley Authority, the Federal Bureau of Investigation, an intelligence component of the Department of Defense (as defined in section 1614 of title 10), or an intelligence activity of a military department covered under subchapter I of chapter 83 of title 10, unless subsection (a)(1)(B) of this section or section 1005(a) of title 39 is the basis for this subchapter's applicability;"],[1,"(9) who is described in section 5102(c)(11) of this title; or"],[1,"(10) who holds a position within the Veterans Health Administration which has been excluded from the competitive service by or under a provision of title 38, unless such employee was appointed to such position under section 7401(3) of such title."],[0,"(c) The Office may provide for the application of this subchapter to any position or group of positions excepted from the competitive service by regulation of the Office which is not otherwise covered by this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7511?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§7511. Definitions; application","tname":"Government Organization and Employees","by":{"0":"45, 46, 46, 46","1":"52","2":"23, 22, 23"}},{"t":"usc","label":"15 U.S.C. § 12","url":"https://www.law.cornell.edu/uscode/text/15/12","stext":{"head":"§12. Definitions; short title","paras":[[0,"(a) \"Antitrust laws,\" as used herein, includes the Act entitled \"An Act to protect trade and commerce against unlawful restraints and monopolies,\" approved July second, eighteen hundred and ninety; sections seventy-three to seventy-six, inclusive, of an Act entitled \"An Act to reduce taxation, to provide revenue for the Government, and for other purposes,\" of August twenty-seventh, eighteen hundred and ninety-four; an Act entitled \"An Act to amend sections seventy-three and seventy-six of the Act of August twenty-seventh, eighteen hundred and ninety-four, entitled 'An Act to reduce taxation, to provide revenue for the Government, and for other purposes,' \" approved February twelfth, nineteen hundred and thirteen; and also this Act."],[0,"\"Commerce,\" as used herein, means trade or commerce among the several States and with foreign nations, or between the District of Columbia or any Territory of the United States and any State, Territory, or foreign nation, or between any insular possessions or other places under the jurisdiction of the United States, or between any such possession or place and any State or Territory of the United States or the District of Columbia or any foreign nation, or within the District of Columbia or any Territory or any insular possession or other place under the jurisdiction of the United States: Provided, That nothing in this Act contained shall apply to the Philippine Islands."],[0,"The word \"person\" or \"persons\" wherever used in this Act shall be deemed to include corporations and associations existing under or authorized by the laws of either the United States, the laws of any of the Territories, the laws of any State, or the laws of any foreign country."],[0,"(b) This Act may be cited as the \"Clayton Act\"."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/12?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§12. Definitions; short title","tname":"Commerce and Trade","by":{"0":"6"}},{"t":"usc","label":"28 U.S.C. § 2201","url":"https://www.law.cornell.edu/uscode/text/28/2201","subs":["(a)"],"stext":{"head":"§2201. Creation of remedy","paras":[[0,"(a) In a case of actual controversy within its jurisdiction, except with respect to Federal taxes other than actions brought under section 7428 of the Internal Revenue Code of 1986, a proceeding under section 505 or 1146 of title 11, or in any civil action involving an antidumping or countervailing duty proceeding regarding a class or kind of merchandise of a free trade area country (as defined in section 516A(f)(9) of the Tariff Act of 1930), as determined by the administering authority, any court of the United States, upon the filing of an appropriate pleading, may declare the rights and other legal relations of any interested party seeking such declaration, whether or not further relief is or could be sought. Any such declaration shall have the force and effect of a final judgment or decree and shall be reviewable as such."],[0,"(b) For limitations on actions brought with respect to drug patents see section 505 or 512 of the Federal Food, Drug, and Cosmetic Act, or section 351 of the Public Health Service Act."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2201?type=usc&year=mostrecent&link-type=html"},"head":"§2201. Creation of remedy","tname":"Judiciary and Judicial Procedure","by":{"0":"42","1":"43-45","2":"21"}},{"t":"usc","label":"28 U.S.C. § 2202","url":"https://www.law.cornell.edu/uscode/text/28/2202","by":{"0":"43"}},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","subs":["(a)"],"by":{"0":"36, 36"}},{"t":"usc","label":"16 U.S.C. § 1385","url":"https://www.law.cornell.edu/uscode/text/16/1385","by":{"0":"19"}},{"t":"usc","label":"34 U.S.C. § 21711","url":"https://www.law.cornell.edu/uscode/text/34/21711","by":{"0":"6"}},{"t":"usc","label":"15 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/15/1681","by":{"0":"6"}},{"t":"usc","label":"15 U.S.C. § 1692","url":"https://www.law.cornell.edu/uscode/text/15/1692","by":{"0":"6"}},{"t":"usc","label":"15 U.S.C. § 41","url":"https://www.law.cornell.edu/uscode/text/15/41","stext":{"head":"§41. Federal Trade Commission established; membership; vacancies; seal","paras":[[0,"A commission is created and established, to be known as the Federal Trade Commission (hereinafter referred to as the Commission), which shall be composed of five Commissioners, who shall be appointed by the President, by and with the advice and consent of the Senate. Not more than three of the Commissioners shall be members of the same political party. The first Commissioners appointed shall continue in office for terms of three, four, five, six, and seven years, respectively, from September 26, 1914, the term of each to be designated by the President, but their successors shall be appointed for terms of seven years, except that any person chosen to fill a vacancy shall be appointed only for the unexpired term of the Commissioner whom he shall succeed: Provided, however, That upon the expiration of his term of office a Commissioner shall continue to serve until his successor shall have been appointed and shall have qualified..1 The President shall choose a chairman from the Commission's membership. No Commissioner shall engage in any other business, vocation, or employment. Any Commissioner may be removed by the President for inefficiency, neglect of duty, or malfeasance in office. A vacancy in the Commission shall not impair the right of the remaining Commissioners to exercise all the powers of the Commission."],[0,"The Commission shall have an official seal, which shall be judicially noticed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/41?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§41. Federal Trade Commission established; membership; vacancies; seal","tname":"Commerce and Trade","by":{"0":"6, 6","1":"5, 7, 16, 22, 25, 30, 38"}},{"t":"usc","label":"15 U.S.C. § 45","url":"https://www.law.cornell.edu/uscode/text/15/45","subs":["(a)(1)","(g)","(l)","(m)","(m)(1)(A)","(m)(1)"],"stext":{"head":"§45. Unfair methods of competition unlawful; prevention by Commission","paras":[[0,"(a) Declaration of unlawfulness; power to prohibit unfair practices; inapplicability to foreign trade"],[0,"(1) Unfair methods of competition in or affecting commerce, and unfair or deceptive acts or practices in or affecting commerce, are hereby declared unlawful."],[0,"(2) The Commission is hereby empowered and directed to prevent persons, partnerships, or corporations, except banks, savings and loan institutions described in section 57a(f)(3) of this title, Federal credit unions described in section 57a(f)(4) of this title, common carriers subject to the Acts to regulate commerce, air carriers and foreign air carriers subject to part A of subtitle VII of title 49, and persons, partnerships, or corporations insofar as they are subject to the Packers and Stockyards Act, 1921, as amended [7 U.S.C. 181 et seq.], except as provided in section 406(b) of said Act [7 U.S.C. 227(b)], from using unfair methods of competition in or affecting commerce and unfair or deceptive acts or practices in or affecting commerce."],[0,"(3) This subsection shall not apply to unfair methods of competition involving commerce with foreign nations (other than import commerce) unless—"],[1,"(A) such methods of competition have a direct, substantial, and reasonably foreseeable effect—"],[2,"(i) on commerce which is not commerce with foreign nations, or on import commerce with foreign nations; or"],[2,"(ii) on export commerce with foreign nations, of a person engaged in such commerce in the United States; and"],[1,"(B) such effect gives rise to a claim under the provisions of this subsection, other than this paragraph."],[0,"If this subsection applies to such methods of competition only because of the operation of subparagraph (A)(ii), this subsection shall apply to such conduct only for injury to export business in the United States."],[0,"(4)(A) For purposes of subsection (a), the term \"unfair or deceptive acts or practices\" includes such acts or practices involving foreign commerce that—"],[1,"(i) cause or are likely to cause reasonably foreseeable injury within the United States; or"],[1,"(ii) involve material conduct occurring within the United States."],[0,"(B) All remedies available to the Commission with respect to unfair and deceptive acts or practices shall be available for acts and practices described in this paragraph, including restitution to domestic or foreign victims."],[0,"(b) Proceeding by Commission; modifying and setting aside orders"],[0,"Whenever the Commission shall have reason to believe that any such person, partnership, or corporation has been or is using any unfair method of competition or unfair or deceptive act or practice in or affecting commerce, and if it shall appear to the Commission that a proceeding by it in respect thereof would be to the interest of the public, it shall issue and serve upon such person, partnership, or corporation a complaint stating its charges in that respect and containing a notice of a hearing upon a day and at a place therein fixed at least thirty days after the service of said complaint. The person, partnership, or corporation so complained of shall have the right to appear at the place and time so fixed and show cause why an order should not be entered by the Commission requiring such person, partnership, or corporation to cease and desist from the violation of the law so charged in said complaint. Any person, partnership, or corporation may make application, and upon good cause shown may be allowed by the Commission to intervene and appear in said proceeding by counsel or in person. The testimony in any such proceeding shall be reduced to writing and filed in the office of the Commission. If upon such hearing the Commission shall be of the opinion that the method of competition or the act or practice in question is prohibited by this subchapter, it shall make a report in writing in which it shall state its findings as to the facts and shall issue and cause to be served on such person, partnership, or corporation an order requiring such person, partnership, or corporation to cease and desist from using such method of competition or such act or practice. Until the expiration of the time allowed for filing a petition for review, if no such petition has been duly filed within such time, or, if a petition for review has been filed within such time then until the record in the proceeding has been filed in a court of appeals of the United States, as hereinafter provided, the Commission may at any time, upon such notice and in such manner as it shall deem proper, modify or set aside, in whole or in part, any report or any order made or issued by it under this section. After the expiration of the time allowed for filing a petition for review, if no such petition has been duly filed within such time, the Commission may at any time, after notice and opportunity for hearing, reopen and alter, modify, or set aside, in whole or in part any report or order made or issued by it under this section, whenever in the opinion of the Commission conditions of fact or of law have so changed as to require such action or if the public interest shall so require, except that (1) the said person, partnership, or corporation may, within sixty days after service upon him or it of said report or order entered after such a reopening, obtain a review thereof in the appropriate court of appeals of the United States, in the manner provided in subsection (c) of this section; and (2) in the case of an order, the Commission shall reopen any such order to consider whether such order (including any affirmative relief provision contained in such order) should be altered, modified, or set aside, in whole or in part, if the person, partnership, or corporation involved files a request with the Commission which makes a satisfactory showing that changed conditions of law or fact require such order to be altered, modified, or set aside, in whole or in part. The Commission shall determine whether to alter, modify, or set aside any order of the Commission in response to a request made by a person, partnership, or corporation under paragraph 1 (2) not later than 120 days after the date of the filing of such request."],[0,"(c) Review of order; rehearing"],[0,"Any person, partnership, or corporation required by an order of the Commission to cease and desist from using any method of competition or act or practice may obtain a review of such order in the court of appeals of the United States, within any circuit where the method of competition or the act or practice in question was used or where such person, partnership, or corporation resides or carries on business, by filing in the court, within sixty days from the date of the service of such order, a written petition praying that the order of the Commission be set aside. A copy of such petition shall be forthwith transmitted by the clerk of the court to the Commission, and thereupon the Commission shall file in the court the record in the proceeding, as provided in section 2112 of title 28. Upon such filing of the petition the court shall have jurisdiction of the proceeding and of the question determined therein concurrently with the Commission until the filing of the record and shall have power to make and enter a decree affirming, modifying, or setting aside the order of the Commission, and enforcing the same to the extent that such order is affirmed and to issue such writs as are ancillary to its jurisdiction or are necessary in its judgement to prevent injury to the public or to competitors pendente lite. The findings of the Commission as to the facts, if supported by evidence, shall be conclusive. To the extent that the order of the Commission is affirmed, the court shall thereupon issue its own order commanding obedience to the terms of such order of the Commission. If either party shall apply to the court for leave to adduce additional evidence, and shall show to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the proceeding before the Commission, the court may order such additional evidence to be taken before the Commission and to be adduced upon the hearing in such manner and upon such terms and conditions as to the court may seem proper. The Commission may modify its findings as to the facts, or make new findings, by reason of the additional evidence so taken, and it shall file such modified or new findings, which, if supported by evidence, shall be conclusive, and its recommendation, if any, for the modification or setting aside of its original order, with the return of such additional evidence. The judgment and decree of the court shall be final, except that the same shall be subject to review by the Supreme Court upon certiorari, as provided in section 1254 of title 28."],[0,"(d) Jurisdiction of court"],[0,"Upon the filing of the record with it the jurisdiction of the court of appeals of the United States to affirm, enforce, modify, or set aside orders of the Commission shall be exclusive."],[0,"(e) Exemption from liability"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/45?type=usc&year=mostrecent&link-type=html"},"head":"§45. Unfair methods of competition unlawful; prevention by Commission","tname":"Commerce and Trade","by":{"0":"6, 7, 27, 7, 27, 25, 7","1":"7"}},{"t":"usc","label":"15 U.S.C. § 45c","url":"https://www.law.cornell.edu/uscode/text/15/45c","by":{"0":"20"}},{"t":"usc","label":"15 U.S.C. § 46","url":"https://www.law.cornell.edu/uscode/text/15/46","subs":["(j)(4)"],"stext":{"head":"§46. Additional powers of Commission","paras":[[0,"The Commission shall also have power—"],[0,"(a) Investigation of persons, partnerships, or corporations"],[0,"To gather and compile information concerning, and to investigate from time to time the organization, business, conduct, practices, and management of any person, partnership, or corporation engaged in or whose business affects commerce, excepting banks, savings and loan institutions described in section 57a(f)(3) of this title, Federal credit unions described in section 57a(f)(4) of this title, and common carriers subject to the Act to regulate commerce, and its relation to other persons, partnerships, and corporations."],[0,"(b) Reports of persons, partnerships, and corporations"],[0,"To require, by general or special orders, persons, partnerships, and corporations, engaged in or whose business affects commerce, excepting banks, savings and loan institutions described in section 57a(f)(3) of this title, Federal credit unions described in section 57a(f)(4) of this title, and common carriers subject to the Act to regulate commerce, or any class of them, or any of them, respectively, to file with the Commission in such form as the Commission may prescribe annual or special, or both annual and special, reports or answers in writing to specific questions, furnishing to the Commission such information as it may require as to the organization, business, conduct, practices, management, and relation to other corporations, partnerships, and individuals of the respective persons, partnerships, and corporations filing such reports or answers in writing. Such reports and answers shall be made under oath, or otherwise, as the Commission may prescribe, and shall be filed with the Commission within such reasonable period as the Commission may prescribe, unless additional time be granted in any case by the Commission."],[0,"(c) Investigation of compliance with antitrust decrees"],[0,"Whenever a final decree has been entered against any defendant corporation in any suit brought by the United States to prevent and restrain any violation of the antitrust Acts, to make investigation, upon its own initiative, of the manner in which the decree has been or is being carried out, and upon the application of the Attorney General it shall be its duty to make such investigation. It shall transmit to the Attorney General a report embodying its findings and recommendations as a result of any such investigation, and the report shall be made public in the discretion of the Commission."],[0,"(d) Investigations of violations of antitrust statutes"],[0,"Upon the direction of the President or either House of Congress to investigate and report the facts relating to any alleged violations of the antitrust Acts by any corporation."],[0,"(e) Readjustment of business of corporations violating antitrust statutes"],[0,"Upon the application of the Attorney General to investigate and make recommendations for the readjustment of the business of any corporation alleged to be violating the antitrust Acts in order that the corporation may thereafter maintain its organization, management, and conduct of business in accordance with law."],[0,"(f) Publication of information; reports"],[0,"To make public from time to time such portions of the information obtained by it hereunder as are in the public interest; and to make annual and special reports to the Congress and to submit therewith recommendations for additional legislation; and to provide for the publication of its reports and decisions in such form and manner as may be best adapted for public information and use: Provided, That the Commission shall not have any authority to make public any trade secret or any commercial or financial information which is obtained from any person and which is privileged or confidential, except that the Commission may disclose such information (1) to officers and employees of appropriate Federal law enforcement agencies or to any officer or employee of any State law enforcement agency upon the prior certification of an officer of any such Federal or State law enforcement agency that such information will be maintained in confidence and will be used only for official law enforcement purposes, and (2) to any officer or employee of any foreign law enforcement agency under the same circumstances that making material available to foreign law enforcement agencies is permitted under section 57b–2(b) of this title."],[0,"(g) Classification of corporations; regulations"],[0,"From time to time classify corporations and (except as provided in section 57a(a)(2) of this title) to make rules and regulations for the purpose of carrying out the provisions of this subchapter."],[0,"(h) Investigations of foreign trade conditions; reports"],[0,"To investigate, from time to time, trade conditions in and with foreign countries where associations, combinations, or practices of manufacturers, merchants, or traders, or other conditions, may affect the foreign trade of the United States, and to report to Congress thereon, with such recommendations as it deems advisable."],[0,"(i) Investigations of foreign antitrust law violations"],[0,"With respect to the International Antitrust Enforcement Assistance Act of 1994 [15 U.S.C. 6201 et seq.], to conduct investigations of possible violations of foreign antitrust laws (as defined in section 12 of such Act [15 U.S.C. 6211])."],[0,"(j) Investigative assistance for foreign law enforcement agencies"],[0,"(1) In general"],[1,"Upon a written request from a foreign law enforcement agency to provide assistance in accordance with this subsection, if the requesting agency states that it is investigating, or engaging in enforcement proceedings against, possible violations of laws prohibiting fraudulent or deceptive commercial practices, or other practices substantially similar to practices prohibited by any provision of the laws administered by the Commission, other than Federal antitrust laws (as defined in section 12(5) of the International Antitrust Enforcement Assistance Act of 1994 (15 U.S.C. 6211(5))), to provide the assistance described in paragraph (2) without requiring that the conduct identified in the request constitute a violation of the laws of the United States."],[0,"(2) Type of assistance"],[1,"In providing assistance to a foreign law enforcement agency under this subsection, the Commission may—"],[2,"(A) conduct such investigation as the Commission deems necessary to collect information and evidence pertinent to the request for assistance, using all investigative powers authorized by this subchapter; and"],[2,"(B) when the request is from an agency acting to investigate or pursue the enforcement of civil laws, or when the Attorney General refers a request to the Commission from an agency acting to investigate or pursue the enforcement of criminal laws, seek and accept appointment by a United States district court of Commission attorneys to provide assistance to foreign and international tribunals and to litigants before such tribunals on behalf of a foreign law enforcement agency pursuant to section 1782 of title 28."],[0,"(3) Criteria for determination"],[1,"In deciding whether to provide such assistance, the Commission shall consider all relevant factors, including—"],[2,"(A) whether the requesting agency has agreed to provide or will provide reciprocal assistance to the Commission;"],[2,"(B) whether compliance with the request would prejudice the public interest of the United States; and"],[2,"(C) whether the requesting agency's investigation or enforcement proceeding concerns acts or practices that cause or are likely to cause injury to a significant number of persons."],[0,"(4) International agreements"],[1,"If a foreign law enforcement agency has set forth a legal basis for requiring execution of an international agreement as a condition for reciprocal assistance, or as a condition for provision of materials or information to the Commission, the Commission, with prior approval and ongoing oversight of the Secretary of State, and with final approval of the agreement by the Secretary of State, may negotiate and conclude an international agreement, in the name of either the United States or the Commission, for the purpose of obtaining such assistance, materials, or information. The Commission may undertake in such an international agreement to—"],[2,"(A) provide assistance using the powers set forth in this subsection;"],[2,"(B) disclose materials and information in accordance with subsection (f) and section 57b–2(b) of this title; and"],[2,"(C) engage in further cooperation, and protect materials and information received from disclosure, as authorized by this subchapter."],[0,"(5) Additional authority"],[1,"The authority provided by this subsection is in addition to, and not in lieu of, any other authority vested in the Commission or any other officer of the United States."],[0,"(6) Limitation"],[1,"The authority granted by this subsection shall not authorize the Commission to take any action or exercise any power with respect to a bank, a savings and loan institution described in section 57a(f)(3) of this title, a Federal credit union described in section 57a(f)(4) of this title, or a common carrier subject to the Act to regulate commerce, except in accordance with the undesignated proviso following the last designated subsection of this section."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/46?type=usc&year=mostrecent&link-type=html"},"head":"§46. Additional powers of Commission","tname":"Commerce and Trade","by":{"0":"7, 28, 28","1":"27"}},{"t":"usc","label":"15 U.S.C. § 53","url":"https://www.law.cornell.edu/uscode/text/15/53","subs":["(b)"],"by":{"0":"7, 25"}},{"t":"usc","label":"15 U.S.C. § 57","url":"https://www.law.cornell.edu/uscode/text/15/57","by":{"0":"36"}},{"t":"usc","label":"15 U.S.C. § 57a","url":"https://www.law.cornell.edu/uscode/text/15/57a","subs":["(a)(1)(B)"],"stext":{"head":"§57a. Unfair or deceptive acts or practices rulemaking proceedings","paras":[[0,"(a) Authority of Commission to prescribe rules and general statements of policy"],[0,"(1) Except as provided in subsection (h), the Commission may prescribe—"],[1,"(A) interpretive rules and general statements of policy with respect to unfair or deceptive acts or practices in or affecting commerce (within the meaning of section 45(a)(1) of this title), and"],[1,"(B) rules which define with specificity acts or practices which are unfair or deceptive acts or practices in or affecting commerce (within the meaning of section 45(a)(1) of this title), except that the Commission shall not develop or promulgate any trade rule or regulation with regard to the regulation of the development and utilization of the standards and certification activities pursuant to this section. Rules under this subparagraph may include requirements prescribed for the purpose of preventing such acts or practices."],[0,"(2) The Commission shall have no authority under this subchapter, other than its authority under this section, to prescribe any rule with respect to unfair or deceptive acts or practices in or affecting commerce (within the meaning of section 45(a)(1) of this title). The preceding sentence shall not affect any authority of the Commission to prescribe rules (including interpretive rules), and general statements of policy, with respect to unfair methods of competition in or affecting commerce."],[0,"(b) Procedures applicable"],[0,"(1) When prescribing a rule under subsection (a)(1)(B) of this section, the Commission shall proceed in accordance with section 553 of title 5 (without regard to any reference in such section to sections 556 and 557 of such title), and shall also (A) publish a notice of proposed rulemaking stating with particularity the text of the rule, including any alternatives, which the Commission proposes to promulgate, and the reason for the proposed rule; (B) allow interested persons to submit written data, views, and arguments, and make all such submissions publicly available; (C) provide an opportunity for an informal hearing in accordance with subsection (c); and (D) promulgate, if appropriate, a final rule based on the matter in the rulemaking record (as defined in subsection (e)(1)(B)), together with a statement of basis and purpose."],[0,"(2)(A) Prior to the publication of any notice of proposed rulemaking pursuant to paragraph (1)(A), the Commission shall publish an advance notice of proposed rulemaking in the Federal Register. Such advance notice shall—"],[1,"(i) contain a brief description of the area of inquiry under consideration, the objectives which the Commission seeks to achieve, and possible regulatory alternatives under consideration by the Commission; and"],[1,"(ii) invite the response of interested parties with respect to such proposed rulemaking, including any suggestions or alternative methods for achieving such objectives."],[0,"(B) The Commission shall submit such advance notice of proposed rulemaking to the Committee on Commerce, Science, and Transportation of the Senate and to the Committee on Energy and Commerce of the House of Representatives. The Commission may use such additional mechanisms as the Commission considers useful to obtain suggestions regarding the content of the area of inquiry before the publication of a general notice of proposed rulemaking under paragraph (1)(A)."],[0,"(C) The Commission shall, 30 days before the publication of a notice of proposed rulemaking pursuant to paragraph (1)(A), submit such notice to the Committee on Commerce, Science, and Transportation of the Senate and to the Committee on Energy and Commerce of the House of Representatives."],[0,"(3) The Commission shall issue a notice of proposed rulemaking pursuant to paragraph (1)(A) only where it has reason to believe that the unfair or deceptive acts or practices which are the subject of the proposed rulemaking are prevalent. The Commission shall make a determination that unfair or deceptive acts or practices are prevalent under this paragraph only if—"],[1,"(A) it has issued cease and desist orders regarding such acts or practices, or"],[1,"(B) any other information available to the Commission indicates a widespread pattern of unfair or deceptive acts or practices."],[0,"(c) Informal hearing procedure"],[0,"The Commission shall conduct any informal hearings required by subsection (b)(1)(C) of this section in accordance with the following procedure:"],[1,"(1)(A) The Commission shall provide for the conduct of proceedings under this subsection by hearing officers who shall perform their functions in accordance with the requirements of this subsection."],[1,"(B) The officer who presides over the rulemaking proceedings shall be responsible to a chief presiding officer who shall not be responsible to any other officer or employee of the Commission. The officer who presides over the rulemaking proceeding shall make a recommended decision based upon the findings and conclusions of such officer as to all relevant and material evidence, except that such recommended decision may be made by another officer if the officer who presided over the proceeding is no longer available to the Commission."],[1,"(C) Except as required for the disposition of ex parte matters as authorized by law, no presiding officer shall consult any person or party with respect to any fact in issue unless such officer gives notice and opportunity for all parties to participate."],[1,"(2) Subject to paragraph (3) of this subsection, an interested person is entitled—"],[2,"(A) to present his position orally or by documentary submission (or both), and"],[2,"(B) if the Commission determines that there are disputed issues of material fact it is necessary to resolve, to present such rebuttal submissions and to conduct (or have conducted under paragraph (3)(B)) such cross-examination of persons as the Commission determines (i) to be appropriate, and (ii) to be required for a full and true disclosure with respect to such issues."],[1,"(3) The Commission may prescribe such rules and make such rulings concerning proceedings in such hearings as may tend to avoid unnecessary costs or delay. Such rules or rulings may include (A) imposition of reasonable time limits on each interested person's oral presentations, and (B) requirements that any cross-examination to which a person may be entitled under paragraph (2) be conducted by the Commission on behalf of that person in such manner as the Commission determines (i) to be appropriate, and (ii) to be required for a full and true disclosure with respect to disputed issues of material fact."],[1,"(4)(A) Except as provided in subparagraph (B), if a group of persons each of whom under paragraphs (2) and (3) would be entitled to conduct (or have conducted) cross-examination and who are determined by the Commission to have the same or similar interests in the proceeding cannot agree upon a single representative of such interests for purposes of cross-examination, the Commission may make rules and rulings (i) limiting the representation of such interest, for such purposes, and (ii) governing the manner in which such cross-examination shall be limited."],[1,"(B) When any person who is a member of a group with respect to which the Commission has made a determination under subparagraph (A) is unable to agree upon group representation with the other members of the group, then such person shall not be denied under the authority of subparagraph (A) the opportunity to conduct (or have conducted) cross-examination as to issues affecting his particular interests if (i) he satisfies the Commission that he has made a reasonable and good faith effort to reach agreement upon group representation with the other members of the group and (ii) the Commission determines that there are substantial and relevant issues which are not adequately presented by the group representative."],[1,"(5) A verbatim transcript shall be taken of any oral presentation, and cross-examination, in an informal hearing to which this subsection applies. Such transcript shall be available to the public."],[0,"(d) Statement of basis and purpose accompanying rule; \"Commission\" defined; judicial review of amendment or repeal of rule; violation of rule"],[0,"(1) The Commission's statement of basis and purpose to accompany a rule promulgated under subsection (a)(1)(B) shall include (A) a statement as to the prevalence of the acts or practices treated by the rule; (B) a statement as to the manner and context in which such acts or practices are unfair or deceptive; and (C) a statement as to the economic effect of the rule, taking into account the effect on small business and consumers."],[0,"(2)(A) The term \"Commission\" as used in this subsection and subsections (b) and (c) includes any person authorized to act in behalf of the Commission in any part of the rulemaking proceeding."],[0,"(B) A substantive amendment to, or repeal of, a rule promulgated under subsection (a)(1)(B) shall be prescribed, and subject to judicial review, in the same manner as a rule prescribed under such subsection. An exemption under subsection (g) shall not be treated as an amendment or repeal of a rule."],[0,"(3) When any rule under subsection (a)(1)(B) takes effect a subsequent violation thereof shall constitute an unfair or deceptive act or practice in violation of section 45(a)(1) of this title, unless the Commission otherwise expressly provides in such rule."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/57a?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§57a. Unfair or deceptive acts or practices rulemaking proceedings","tname":"Commerce and Trade","by":{"0":"7, 26"}},{"t":"usc","label":"15 U.S.C. § 57b","url":"https://www.law.cornell.edu/uscode/text/15/57b","subs":["(b)"],"by":{"0":"7, 25"}},{"t":"usc","label":"15 U.S.C. § 69f","url":"https://www.law.cornell.edu/uscode/text/15/69f","subs":["(b)"],"by":{"0":"26"}},{"t":"usc","label":"15 U.S.C. § 18a","url":"https://www.law.cornell.edu/uscode/text/15/18a","by":{"0":"7, 26, 27"}},{"t":"usc","label":"15 U.S.C. § 3051","url":"https://www.law.cornell.edu/uscode/text/15/3051","by":{"0":"6"}},{"t":"usc","label":"15 U.S.C. § 3053","url":"https://www.law.cornell.edu/uscode/text/15/3053","by":{"0":"20, 26"}},{"t":"usc","label":"15 U.S.C. § 3057","url":"https://www.law.cornell.edu/uscode/text/15/3057","subs":["(d)"],"by":{"0":"27"}},{"t":"usc","label":"15 U.S.C. § 3058","url":"https://www.law.cornell.edu/uscode/text/15/3058","subs":["(b)"],"by":{"0":"27"}},{"t":"law","label":"Pub. L. No. 100-191","url":"https://www.govinfo.gov/link/statute/101/1305","by":{"0":"45","1":"51"}},{"t":"usc","label":"15 U.S.C. § 1051","url":"https://www.law.cornell.edu/uscode/text/15/1051","by":{"0":"6"}},{"t":"law","label":"Pub. L. No. 108-173","url":"https://www.govinfo.gov/link/plaw/108/public/173","by":{"0":"27"}},{"t":"usc","label":"10 U.S.C. § 987","url":"https://www.law.cornell.edu/uscode/text/10/987","by":{"0":"6"}},{"t":"usc","label":"15 U.S.C. § 6301","url":"https://www.law.cornell.edu/uscode/text/15/6301","by":{"0":"6"}},{"t":"usc","label":"15 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/15/1","stext":{"head":"§1. Trusts, etc., in restraint of trade illegal; penalty","paras":[[0,"Every contract, combination in the form of trust or otherwise, or conspiracy, in restraint of trade or commerce among the several States, or with foreign nations, is declared to be illegal. Every person who shall make any contract or engage in any combination or conspiracy hereby declared to be illegal shall be deemed guilty of a felony, and, on conviction thereof, shall be punished by fine not exceeding $100,000,000 if a corporation, or, if any other person, $1,000,000, or by imprisonment not exceeding 10 years, or by both said punishments, in the discretion of the court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§1. Trusts, etc., in restraint of trade illegal; penalty","tname":"Commerce and Trade","by":{"0":"6"}},{"t":"usc","label":"7 U.S.C. § 227","url":"https://www.law.cornell.edu/uscode/text/7/227","subs":["(b)"],"by":{"0":"19"}},{"t":"usc","label":"15 U.S.C. § 1607","url":"https://www.law.cornell.edu/uscode/text/15/1607","subs":["(c)"],"by":{"0":"36"}},{"t":"usc","label":"15 U.S.C. § 2051","url":"https://www.law.cornell.edu/uscode/text/15/2051","by":{"0":"36"}},{"t":"usc","label":"15 U.S.C. § 7607","url":"https://www.law.cornell.edu/uscode/text/15/7607","by":{"0":"19"}},{"t":"usc","label":"16 U.S.C. § 1862","url":"https://www.law.cornell.edu/uscode/text/16/1862","by":{"0":"20"}},{"t":"usc","label":"29 U.S.C. § 166","url":"https://www.law.cornell.edu/uscode/text/29/166","by":{"0":"36"}},{"t":"case","label":"Aetna Life Ins. Co. v. Hayworth","cite":"300 U.S. 227","y":1937,"id":"scdb/1936-068","sc":1,"sum":"1. The Federal Declaratory Judgment Act deals with \"controversies\" in the constitutional sense and is procedural only.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Arizona v. Rumsey","cite":"467 U.S. 203","y":1984,"id":"1983/83-226","sc":1,"op":1,"sum":"The Double Jeopardy Clause prohibits Arizona from sentencing respondent to death. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"39"}},{"t":"case","label":"Atl. Richfield Co. v. Christian","cite":"590 U.S. 1","y":2020,"url":"https://supreme.justia.com/cases/federal/us/590/1/","sc":1,"by":{"1":"51"}},{"t":"case","label":"Baer Bros. Mercantile Co. v. Denver & Rio Grande R.R. Co.","cite":"233 U.S. 479","y":1914,"id":"scdb/1913-153","sc":1,"sum":"Awarding reparation for excessive charges in the past and regulating rates for the future involve the determination of matters essentially different; while they may be dealt with in one order by the Interstate Commerce Commission, an order for reparation is not void because it does not fix the' rate for the future.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"CFPB v. Cmty. Fin. Servs. Ass’n","cite":"601 U.S. 416","y":2024,"id":"2023/22-448","sc":1,"sum":"Congress’ statutory authorization allowing the Consumer Financial Protection Bureau to draw money from the earnings of the Federal Reserve System to carry out the Bureau’s duties, 12 U. S. C. §§5497(a)(1), (2), satisfies the Appropriations Clause.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"17"}},{"t":"case","label":"Clinton v. City of New York","cite":"524 U.S. 417","y":1998,"id":"1997/97-1374","sc":1,"sum":"A case in which the Court declared that pieces of legislation passed by both houses of Congress must be either passed or vetoed as a whole, not in separate parts.","sumSrc":"Oyez","by":{"1":"50"}},{"t":"case","label":"Dobbs v. Women’s Health Org.","cite":"597 U.S. 215","y":2022,"url":"https://supreme.justia.com/cases/federal/us/597/215/","sc":1,"op":4,"by":{"1":"32, 35"}},{"t":"case","label":"(v) Free Enter. Fund v. PCAOB","cite":"537 F.3d 667","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/537/667/","op":1,"by":{"1":"34"}},{"t":"case","label":"FTC v. Brown Shoe Co.","cite":"384 U.S. 316","y":1966,"id":"1965/118","sc":1,"sum":"The FTC acted well within its authority under the Act in declaring respondent's franchise program an unfair, trade practice.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"6"}},{"t":"case","label":"Gamble v. United States","cite":"587 U.S. 678","y":2019,"id":"2018/17-646","sc":1,"sum":"The dual sovereignty doctrine—under which two offenses are not the “same offence” for double jeopardy purposes if prosecuted by separate sovereigns—is upheld.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"32"}},{"t":"case","label":"Great-West Life & Annuity Ins. Co. v. Knudson","cite":"534 U.S. 204","y":2002,"id":"2001/99-1786","sc":1,"sum":"The Court held that because Great-West is seeking legal relief - the imposition of personal liability on Knudson for a contractual obligation to pay money - ERISA does not authorize this action.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"Hilton v. S.C. Pub. Rys. Comm’n","cite":"502 U.S. 197","y":1991,"id":"1991/90-848","sc":1,"op":2,"sum":"FELA creates a cause of action against a state-owned railroad, enforceable in state court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36"}},{"t":"case","label":"ICC v. Cincinnati, N. O. & T. P. R. Co.","cite":"167 U.S. 479","y":1897,"id":"scdb/1896-212","sc":1,"sum":"Congress has not conferred upon the Interstate Commerce Commission the legislative power of prescribing rates either maximum or minimum or absolute; and, as it did not give the express power to the commission, it did not intend to secure the same result indirectly by empowering that tribunal to determine what in reference to the past was reasonable and just, whether as maximum, minimum or absolute, and then enable …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"6"}},{"t":"case","label":"Kalbfus v. Siddons","cite":"42 App. D.C. 310","y":1914,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/App.%20D.C./42/310/","by":{"1":"42"}},{"t":"case","label":"Lyon v. Comm’rs of Granville Cnty.","cite":"26 S.E. 929","y":1897,"court":"N.C.","url":"https://www.courtlistener.com/c/S.E./26/929/","by":{"1":"42"}},{"t":"case","label":"Marsh v. Chambers","cite":"463 U.S. 783","y":1983,"id":"1982/82-23","sc":1,"sum":"As a consequence, the chaplaincy practice had become \"part of the fabric of our society.\" In such circumstances, an invocation for Divine guidance is not an establishment of religion. \"It is,\" wrote Burger, \"simply a tolerable acknowledgment of beliefs widely held among the people of this country.\".","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Miller v. French","cite":"530 U.S. 327","y":2000,"id":"1999/99-224","sc":1,"sum":"The Court held that Congress clearly intended to make operation of the PLRA's automatic stay provision mandatory, precluding courts from exercising their equitable power to enjoin the stay and that the PLRA does not violate separation of powers principles.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"op":3,"sum":"A case in which the Court further defined the limitations on the presidential powers granted by the Recess Appointments Clause.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Peters v. Hobby","cite":"349 U.S. 331","y":1955,"id":"scdb/1954-088","sc":1,"sum":"During his employment as a special consultant in a federal agency, petitioner had been twice cleared by the agency's loyalty board. Subsequently, acting solely on its own motion, the Civil Service Commission's Loyalty. Review Board (established under Executive Order 9835) determined that there was a reasonable doubt as to petitioner's loyalty and notified him that he was barred from federal service for a period of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"Rex v. Blooer","cite":"97 Eng. Rep. 697","y":1760,"court":"K.B.","url":"https://www.courtlistener.com/c/Eng.%20Rep./97/697/","by":{"1":"41, 51"}},{"t":"case","label":"Sampson v. Murray","cite":"415 U.S. 61","y":1974,"id":"1973/72-403","sc":1,"sum":"Upon being notified that she was' going to be discharged on a specific date from her position as aprobationary Government employee, respondent filed this action claiming that the applicable Civil Service regulations for discharge of probationary employees had not been followed, and seeking a temporary injunction against her dismissal pending an administrative appeal to the Civil Service Commission (CSC). The …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"Sanchez-Espinoza v. Reagan","cite":"770 F.2d 202","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/770/202/","by":{"1":"43, 47"}},{"t":"case","label":"Service v. Dulles","cite":"354 U.S. 363","y":1957,"id":"1956/407","sc":1,"op":1,"ar":1,"sum":"Petitioner's discharge was invalid, because it violated Regulations of the Department of State which were binding on the Secretary; and the judgment is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46, 47"}},{"t":"case","label":"South Dakota v. Wayfair","cite":"585 U.S. 162","y":2018,"id":"2017/17-494","sc":1,"op":3,"sum":"A case in which the Court overruled Quill Corp. v. North Dakota and National Bellas Hess, Inc. v. Department of Revenue of Illinois, holding that states may require sellers with no physical presence in the state to collect and remit sales tax for goods sold within the state.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Stern v. Marshall","cite":"564 U.S. 462","y":2011,"id":"2010/10-179","sc":1,"op":1,"sum":"The Court held that the Bankruptcy Court did not have the constitutional authority to enter judgement on the petitioner's counterclaim.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Vitarelli v. Seaton","cite":"359 U.S. 535","y":1959,"id":"1958/101","sc":1,"op":1,"sum":"Petitioner's dismissal was illegal and he is entitled to reinstatement.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Watson v. Sutherland","cite":"72 U.S. 74","y":1866,"id":"scdb/1866-088","sc":1,"op":9,"ar":2,"sum":"Watson & Co., appellants in the suit, having issued writs offieri facias on certain judgments which they had recovered in the Circuit Court for the District of Maryland against Wroth & Fullerton, caused them to be levied on the entire stock in trade of a retail dry goods store in Baltimore, in 'the possession of one Sutherland, the appellee. Sutherland, claiming the exclusive ownership of the property, and insisting …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"45"}},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Kerry","cite":"576 U.S. 1","y":2015,"id":"2014/13-628","sc":1,"op":2,"sum":"The Court held that a federal statute directing the Secretary of State to record the birthplace of a citizen born in Jerusalem as “Israel” if requested to do so impermissibly infringed on the President’s power to recognize foreign states.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"const","label":"Article I","by":{"1":"49"}},{"t":"usc","label":"5 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/5/1201","by":{"1":"37"}},{"t":"usc","label":"5 U.S.C. § 1202","url":"https://www.law.cornell.edu/uscode/text/5/1202","subs":["(d)"],"stext":{"head":"§1202. Term of office; filling vacancies; removal","paras":[[0,"(a) The term of office of each member of the Merit Systems Protection Board is 7 years."],[0,"(b) A member appointed to fill a vacancy occurring before the end of a term of office of the member's predecessor serves for the remainder of that term. Any appointment to fill a vacancy is subject to the requirements of section 1201. Any new member serving only a portion of a seven-year term in office may continue to serve until a successor is appointed and has qualified, except that such member may not continue to serve for more than one year after the date on which the term of the member would otherwise expire, unless reappointed."],[0,"(c) Any member appointed for a 7-year term may not be reappointed to any following term but may continue to serve beyond the expiration of the term until a successor is appointed and has qualified, except that such member may not continue to serve for more than one year after the date on which the term of the member would otherwise expire under this section."],[0,"(d) Any member may be removed by the President only for inefficiency, neglect of duty, or malfeasance in office."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/1202?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1202. Term of office; filling vacancies; removal","tname":"Government Organization and Employees","by":{"1":"37"}},{"t":"usc","label":"5 U.S.C. § 1204","url":"https://www.law.cornell.edu/uscode/text/5/1204","by":{"1":"37"}},{"t":"usc","label":"5 U.S.C. § 7703","url":"https://www.law.cornell.edu/uscode/text/5/7703","by":{"1":"37"}},{"t":"usc","label":"12 U.S.C. § 504","url":"https://www.law.cornell.edu/uscode/text/12/504","stext":{"head":"§504. Civil money penalty","paras":[[0,"(a) First tier"],[0,"Any member bank which, and any institution-affiliated party (within the meaning of section 1813(u) of this title) with respect to such member bank who, violates any provision of section 371c, 371c–1, 375, 375a, 375b, 376, or 503 of this title, or any regulation issued pursuant thereto, shall forfeit and pay a civil penalty of not more than $5,000 for each day during which such violation continues."],[0,"(b) Second tier"],[0,"Notwithstanding subsection (a), any member bank which, and any institution-affiliated party (within the meaning of section 1813(u) of this title) with respect to such member bank who 1"],[1,"(1)(A) commits any violation described in subsection (a);"],[1,"(B) recklessly engages in an unsafe or unsound practice in conducting the affairs of such member bank; or"],[1,"(C) breaches any fiduciary duty;"],[1,"(2) which violation, practice, or breach—"],[2,"(A) is part of a pattern of misconduct;"],[2,"(B) causes or is likely to cause more than a minimal loss to such member bank; or"],[2,"(C) results in pecuniary gain or other benefit to such party,"],[0,"shall forfeit and pay a civil penalty of not more than $25,000 for each day during which such violation, practice, or breach continues."],[0,"(c) Third tier"],[0,"Notwithstanding subsections (a) and (b), any member bank which, and any institution-affiliated party (within the meaning of section 1813(u) of this title) with respect to such member bank who—"],[1,"(1) knowingly—"],[2,"(A) commits any violation described in subsection (a);"],[2,"(B) engages in any unsafe or unsound practice in conducting the affairs of such credit union; 2 or"],[2,"(C) breaches any fiduciary duty; and"],[1,"(2) knowingly or recklessly causes a substantial loss to such credit union 2 or a substantial pecuniary gain or other benefit to such party by reason of such violation, practice, or breach,"],[0,"shall forfeit and pay a civil penalty in an amount not to exceed the applicable maximum amount determined under subsection (d) for each day during which such violation, practice, or breach continues."],[0,"(d) Maximum amounts of penalties for any violation described in subsection (c)"],[0,"The maximum daily amount of any civil penalty which may be assessed pursuant to subsection (c) for any violation, practice, or breach described in such subsection is—"],[1,"(1) in the case of any person other than a member bank, an amount to not exceed $1,000,000; and"],[1,"(2) in the case of a member bank, an amount not to exceed the lesser of—"],[2,"(A) $1,000,000; or"],[2,"(B) 1 percent of the total assets of such member bank."],[0,"(e) Assessment; etc."],[0,"Any penalty imposed under subsection (a), (b), or (c) shall be assessed and collected 3 by"],[1,"(1) in the case of a national bank, by the Comptroller of the Currency; and"],[1,"(2) in the case of a State member bank, by the Board,"],[0,"in the manner provided in subparagraphs (E), (F), (G), and (I) of section 1818(i)(2) of this title for penalties imposed (under such section) and any such assessment shall be subject to the provisions of such section."],[0,"(f) Hearing"],[0,"The member bank or other person against whom any penalty is assessed under this section shall be afforded an agency hearing if such member bank or person submits a request for such hearing within 20 days after the issuance of the notice of assessment. Section 1818(h) of this title shall apply to any proceeding under this section."],[0,"(g) Disbursement"],[0,"All penalties collected under authority of this paragraph shall be deposited into the Treasury."],[0,"(h) \"Violate\" defined"],[0,"For purposes of this section, the term \"violate\" includes any action (alone or with another or others) for or toward causing, bringing about, participating in, counseling, or aiding or abetting a violation."],[0,"(i) Regulations"],[0,"The Comptroller of the Currency and the Board shall prescribe regulations establishing such procedures as may be necessary to carry out this section."],[0,"(m) 4 Notice under this section after separation from service"],[0,"The resignation, termination of employment or participation, or separation of an institution-affiliated party (within the meaning of section 1813(u) of this title) with respect to a member bank (including a separation caused by the closing of such a bank) shall not affect the jurisdiction and authority of the appropriate Federal banking agency to issue any notice and proceed under this section against any such party, if such notice is served before the end of the 6-year period beginning on the date such party ceased to be such a party with respect to such bank (whether such date occurs before, on, or after August 9, 1989)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/504?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§504. Civil money penalty","tname":"Banks and Banking","by":{"1":"29"}},{"t":"usc","label":"12 U.S.C. § 4009","url":"https://www.law.cornell.edu/uscode/text/12/4009","subs":["(c)"],"by":{"1":"29"}},{"t":"law","label":"Pub. L. No. 96-252","url":"https://www.govinfo.gov/link/statute/94/374","by":{"1":"7"}},{"t":"law","label":"Pub. L. No. 103-312","url":"https://www.govinfo.gov/link/statute/108/1691","by":{"1":"8"}},{"t":"law","label":"Pub. L. No. 111-203","url":"https://www.govinfo.gov/link/plaw/111/public/203","by":{"1":"8"}},{"t":"reg","label":"16 C.F.R. § 0.8","url":"https://www.ecfr.gov/current/title-16/section-0.8","by":{"1":"7","2":"14"}},{"t":"rule","label":"Fed. R. Civ. P. 81","url":"https://www.law.cornell.edu/rules/frcp/rule_81","subs":["(b)"],"by":{"1":"47"}},{"t":"case","label":"AFGE v. Secretary of Air Force","cite":"716 F.3d 633","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/716/633/","by":{"2":"23"}},{"t":"case","label":"Andrade v. Lauer","cite":"729 F.2d 1475","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/729/1475/","by":{"2":"22"}},{"t":"case","label":"Barr v. AAPC, Inc.","cite":"591 U.S. 610","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/610/","sc":1,"op":30,"ar":1,"by":{"2":"13"}},{"t":"case","label":"Brown v. Board of Education","cite":"347 U.S. 483","y":1954,"id":"1940-1955/347us483","sc":1,"op":1,"ar":3,"sum":"The Court decided that the \"separate but equal\" standards of racial segregation were unconstitutional, paving the way for the Civil Rights Movement and national desegregation.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Dellinger v. Bessent","cite":"2025 WL 559669","y":2025,"court":"D.C. Cir. Feb. 15","by":{"2":"20"}},{"t":"case","label":"FCC v. Fox Television Stations, Inc.","cite":"556 U.S. 502","y":2009,"id":"2008/07-582","sc":1,"op":2,"sum":"The Court held that the FCC's imposition of liability on Fox Television Stations for fleeting expletives was not \"arbitrary and capricious\" under the Administrative Procedure Act, even though the FCC previously accepted similar expletives.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"Filebark v. U.S. Department of Transportation","cite":"555 F.3d 1009","y":2009,"url":"https://www.courtlistener.com/c/F.3d/555/1009/","by":{"2":"23"}},{"t":"case","label":"Heckler v. Chaney","cite":"470 U.S. 821","y":1985,"id":"1984/83-1878","sc":1,"ar":1,"sum":"They are presumptively unreviewable. Refusals of administrative agencies to exercise enforcement authority involve a complicated balancing of factors, including agency allocation of scarce resources, which are not suitable for judicial review. Thus, they are presumptively \"committed to agency discretion by law\" under Section 701(a)(2).","sumSrc":"Oyez","by":{"2":"6"}},{"t":"case","label":"Janus v. AFSCME","cite":"585 U.S. 878","y":2018,"url":"https://supreme.justia.com/cases/federal/us/585/878/","sc":1,"by":{"2":"19"}},{"t":"case","label":"Korematsu v. United States","cite":"323 U.S. 214","y":1944,"id":"1940-1955/323us214","sc":1,"sum":"The Court held that compulsory exclusion of citizens during times of war is justified in order to reduce the risk of espionage.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Medellín v. Texas","cite":"552 U.S. 491","y":2008,"id":"2007/06-984","sc":1,"sum":"The Court held that the signed Protocol of the Vienna Convention did not make the treaty self-executing and, therefore, the treaty is not binding upon state courts until it is enacted into law by Congress.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"Nyunt v. Chairman, Broadcasting Board of Governors","cite":"589 F.3d 445","y":2009,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/589/445/","by":{"2":"23"}},{"t":"case","label":"Plessy v. Ferguson","cite":"163 U.S. 537","y":1896,"id":"1850-1900/163us537","sc":1,"sum":"The Court held that state-mandated segregation laws did not violate the equal protection clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Severino v. Biden","cite":"71 F.4th 1038","y":2023,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/71/1038/","by":{"2":"9"}},{"t":"case","label":"Trump v. Hawaii","cite":"585 U.S. 667","y":2018,"id":"2017/17-965","sc":1,"sum":"The Court held that President Donald Trump’s Proclamation restricting travel and immigration to the US from certain countries (“travel ban”) does not violate the president’s statutory authority or the Establishment Clause of the Constitution. The Court was also asked, but did not decide, whether a global injunction barring enforcement of parts of the Proclamation is impermissibly overbroad.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"United States v. Texas","cite":"599 U.S. 670","y":2023,"id":"2022/22-58","sc":1,"op":1,"sum":"Texas and Louisiana lack Article III standing to challenge immigration-enforcement guidelines promulgated by the Secretary of Homeland Security that prioritize the arrest and removal of certain noncitizens from the United States.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"6"}},{"t":"case","label":"Wallace v. Anderson","cite":"5 Wheat. 291","y":1820,"url":"https://www.courtlistener.com/c/Wheat./5/291/","by":{"2":"22"}},{"t":"usc","label":"5 U.S.C. § 2101","url":"https://www.law.cornell.edu/uscode/text/5/2101","subs":["(1)"],"by":{"2":"22"}},{"t":"usc","label":"15 U.S.C. § 2076","url":"https://www.law.cornell.edu/uscode/text/15/2076","subs":["(b)(7)"],"by":{"2":"6"}},{"t":"case","label":"William Van Alstyne, A Critical Guide to Marbury v. Madison","cite":"1969 Duke L.J. 1","url":"https://www.courtlistener.com/c/Duke%20L.J./1969/1/","op":9,"by":{"2":"20"}}]};